<?php $statusLabels = ['draft' => 'مسودة', 'approved' => 'معتمد', 'cancelled' => 'ملغي']; $isDraft = $certificate['status'] === 'draft'; ?>
<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><div class="page-pretitle"><?= e($certificate['subcontract_code'] . ' - ' . $certificate['subcontract_title']) ?></div><h2 class="page-title"><?= e($certificate['certificate_code']) ?></h2></div><div class="col-auto d-flex gap-2"><a class="btn" href="/subcontracts/<?= (int) $certificate['subcontract_id'] ?>/certificates">العودة للمستخلصات</a><?php if ($isDraft && $canEdit): ?><a class="btn" href="/subcontract-certificates/<?= (int) $certificate['id'] ?>/edit">تعديل المسودة</a><?php endif; ?></div></div></div>
<div class="card mb-4"><div class="card-body"><div class="row g-3"><div class="col-md-3"><div class="text-secondary">الرقم المرجعي</div><strong><?= e($certificate['certificate_number'] ?? '—') ?></strong></div><div class="col-md-3"><div class="text-secondary">التاريخ</div><strong><?= e($certificate['certificate_date']) ?></strong></div><div class="col-md-3"><div class="text-secondary">الفترة</div><strong><?= e(($certificate['period_from'] ?? '—') . ' إلى ' . ($certificate['period_to'] ?? '—')) ?></strong></div><div class="col-md-3"><div class="text-secondary">الحالة</div><span class="badge bg-blue-lt"><?= $statusLabels[$certificate['status']] ?></span></div></div></div></div>
<?php if ($certificate['pricing_method'] === 'boq'): ?><div class="card mb-4"><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>البند</th><th>الوحدة</th><th>كمية العقد</th><th>السابقة</th><th>الحالية</th><th>التراكمية</th><th>السعر</th><th>القيمة الحالية</th><th>القيمة التراكمية</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['description_snapshot']) ?></td><td><?= e($item['unit_name_snapshot']) ?></td><td><?= e($item['contract_quantity']) ?></td><td><?= e($isDraft ? $item['live_previous_quantity'] : $item['previous_quantity']) ?></td><td><?= e($item['current_quantity']) ?></td><td><?= e($isDraft ? $item['live_cumulative_quantity'] : $item['cumulative_quantity']) ?></td><td><?= e($item['unit_rate']) ?></td><td><?= e($isDraft ? $item['live_current_amount'] : $item['current_amount']) ?></td><td><?= e($isDraft ? $item['live_cumulative_amount'] : $item['cumulative_amount']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php else: ?><div class="card mb-4"><div class="card-body"><div class="row g-3"><div class="col-md-3"><div class="text-secondary">النسبة السابقة</div><strong><?= e($certificate['previous_progress_percentage'] ?? 'تحسب عند الاعتماد') ?>%</strong></div><div class="col-md-3"><div class="text-secondary">النسبة الحالية</div><strong><?= e($certificate['current_progress_percentage']) ?>%</strong></div><div class="col-md-3"><div class="text-secondary">النسبة التراكمية</div><strong><?= e($certificate['cumulative_progress_percentage'] ?? 'تحسب عند الاعتماد') ?>%</strong></div><div class="col-md-3"><div class="text-secondary">قيمة العقد</div><strong><?= e($certificate['contract_value']) ?></strong></div></div></div></div><?php endif; ?>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="card card-sm"><div class="card-body"><div class="text-secondary">القيمة السابقة</div><div class="h2"><?= e($certificate['previous_earned_value'] ?? 'تحسب عند الاعتماد') ?></div></div></div></div><div class="col-md-4"><div class="card card-sm"><div class="card-body"><div class="text-secondary">القيمة الحالية</div><div class="h2"><?= e($certificate['current_earned_value'] ?? 'تحسب عند الاعتماد') ?></div></div></div></div><div class="col-md-4"><div class="card card-sm"><div class="card-body"><div class="text-secondary">القيمة التراكمية</div><div class="h2 text-success"><?= e($certificate['cumulative_earned_value'] ?? 'تحسب عند الاعتماد') ?></div></div></div></div></div>
<?php if ($isDraft): ?><div class="d-flex gap-2"><?php if ($canApprove): ?><form method="post" action="/subcontract-certificates/<?= (int) $certificate['id'] ?>/approve" class="js-confirm-form" data-confirm-text="سيتم تجميد الكميات والقيم نهائيًا بعد الاعتماد."><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><button class="btn btn-success">اعتماد المستخلص</button></form><?php endif; ?><?php if ($canCancel): ?><form method="post" action="/subcontract-certificates/<?= (int) $certificate['id'] ?>/cancel" class="js-confirm-form" data-confirm-text="سيتم إلغاء المسودة ولن تؤثر في القيمة المكتسبة."><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><button class="btn btn-danger">إلغاء المسودة</button></form><?php endif; ?></div><?php endif; ?>
